1	// 分组非运行时段告警与快照救援事务 —— 本地离线回归测试。
2	//
3	// 运行(在仓库根目录):
4	//   node tests/run.mjs
5	// 要求 Node.js 24,无外部依赖;可重复离线运行。
6	//
7	// 测试约定:
8	// - 每个场景使用独立的 OS 临时数据目录(METERWATCH_DATA_DIR),结束即清理,
9	//   绝不触碰默认 ~/.meterwatch 或其他使用者数据。
10	// - 主要场景一律以「新进程」运行现有命令入口 `node app.ts ...`,核对退出码、
11	//   业务输出(stdout/stderr)与三个业务存储(readings/alerts/groups)的持久化状态。
12	// - R1..R4 覆盖显式救援(rescue):日志损坏拒绝、留存字节与缺失状态、中断续接、
13	//   回退方向钉死,以及收尾读写失败的回退保证。R4 用产品内置的离线故障钩子
14	//   (环境变量 METERWATCH_TEST_FAULT,仅测试时设置,正常使用零行为)在三个存储
15	//   已经换入后的完成记录写入、事务材料清理与回退方向记录写入处制造可控失败,
16	//   核对退出码、无成功输出、全部固定文件的字节与存在状态,以及解除故障后的
17	//   跨进程回退(故障必须真实到达收尾,不以获取锁失败代替)。
18	// - 全部断言通过进程退出码 0;任一失败退出码非零并指出场景名。
19	//
20	// 预期值全部在下方 EXPECTED 中按口径手工/独立推导(原读数区间起点累计比例
21	// 向下取整、BigInt 整数运算),不复用产品的计算函数,也不拿两份产品输出
22	// 互相比较来充当预期值。
23	
24	import { spawnSync, execFileSync } from 'node:child_process';
25	import { mkdtempSync, writeFileSync, readFileSync, existsSync, rmSync, statSync, mkdirSync, copyFileSync } from 'node:fs';
26	import { tmpdir } from 'node:os';
27	import { join, dirname } from 'node:path';
28	import { fileURLToPath } from 'node:url';
29	
30	const APP = fileURLToPath(new URL('../app.ts', import.meta.url));
31	
32	// ---------------------------------------------------------------------------
33	// 独立推导的预期值(非产品代码):
34	//
35	// 主场景 S1,UTC 2026-01-05(周一),运行窗口 mon 12:00-18:00(等价拆分重试
36	// 使用 mon 12:00-15:00 + mon 15:00-18:00):
37	//   非运行 UTC 时段 = [00:00,12:00) + [18:00,24:00),共 64800 秒;
38	//   运行 UTC 时段   = [12:00,18:00),            共 21600 秒。
39	// 分摊口径 cum(diff,start,dur,t)=floor(diff*(t-start)/dur),片段=两端累计量之差。
40	//   m1 区间 [周一00:00,周二00:00) dur=86400,diff=9007199254742001 毫千瓦时
41	//      (超出 Number.MAX_SAFE_INTEGER=9007199254740991;不能被 86400 整除):
42	//      NR 段1[00,12)=4503599627371000;运行[12,18)=2251799813685500;
43	//      NR 段2[18,24)=2251799813685501。m1 非运行合计 = 6755399441056501。
44	//   m2 区间 [00:00,24:00) diff=2000 毫千瓦时:非运行 = 1000(=1.000 kWh)。
45	//   m3 自 12:00:30(秒级成员切换,落在运行窗内)起为成员,其首条读数在 12:01:00;
46	//      有效读数区间 [12:01:00,24:00) dur=43140,diff=7:
47	//      运行窗切点 18:00 的累计量 = floor(7*(64800-43260)/43140)=floor(7*21540/43140)=3;
48	//      非运行[18,24)=cum(24:00)−cum(18:00)=7−3=4。
