function mergeGapList(into: GapDetail[], add: GapDetail[]): void {
  const seen = new Set(into.map((g) => `${g.device ?? ''} ${g.start} ${g.end}`));
  for (const g of add) {
    const key = `${g.device ?? ''} ${g.start} ${g.end}`;
    if (!seen.has(key)) {
      seen.add(key);
      into.push(g);
    }
  }
}

