    }
    maxInterval = parsed;
  }
  return cmdGroupCompare({
    id,
    referenceFrom: refFrom,
    referenceTo: refTo,
    compareFrom: cmpFrom,
    compareTo: cmpTo,
    maxInterval,
  });
